#!/usr/bin/env bash
# Builds the native iOS app on a macOS machine without signing (PLATFORMS.md "Native iOS"):
#   1. Cocos Creator (CLI) exports the project: game/build/ios — assets, scripts and an Xcode
#      project generated by CMake from game/native/engine/ios;
#   2. xcodebuild compiles it for devices with code signing off;
#   3. the .app goes into Payload/ and is zipped as an .ipa, which Sideloadly signs with the
#      user's own Apple ID while installing it.
#
# Usage: tools/ci/build-ios.sh <path to CocosCreator.app> <output dir>
# Logs: <output dir>/cocos.log and <output dir>/xcode.log.

set -euo pipefail

CREATOR_APP="$1"
OUT="$(mkdir -p "$2" && cd "$2" && pwd)"
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
PROJECT="$ROOT/game"
CONFIG="$ROOT/build-configs/ios.json"
EXPORT="$PROJECT/build/ios"

echo "== Cocos Creator: export the iOS project"
set +e
"$CREATOR_APP/Contents/MacOS/CocosCreator" --project "$PROJECT" --build "configPath=$CONFIG" 2>&1 | tee "$OUT/cocos.log"
code=${PIPESTATUS[0]}
set -e
# Cocos exit codes: 36 is success, 32 bad parameters, 34 a failed build.
if [ "$code" != "36" ]; then
  echo "Cocos build failed with exit code $code"
  exit 1
fi

XCODEPROJ="$(find "$EXPORT/proj" -maxdepth 1 -name '*.xcodeproj' | head -n 1)"
if [ -z "$XCODEPROJ" ]; then
  echo "No Xcode project in $EXPORT/proj"
  ls -la "$EXPORT" "$EXPORT/proj" || true
  exit 1
fi
# The app's target (and its scheme) is named after packages.ios.executableName in the config.
SCHEME="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["packages"]["ios"]["executableName"])' "$CONFIG")"
echo "== xcodebuild: $XCODEPROJ, scheme $SCHEME"
xcodebuild -list -project "$XCODEPROJ" | sed -n '/Schemes:/,$p' | head -n 20

set +e
xcodebuild build \
  -project "$XCODEPROJ" \
  -scheme "$SCHEME" \
  -configuration Release \
  -sdk iphoneos \
  -destination 'generic/platform=iOS' \
  -parallelizeTargets \
  CODE_SIGNING_ALLOWED=NO CODE_SIGNING_REQUIRED=NO CODE_SIGN_IDENTITY="" DEVELOPMENT_TEAM="" \
  > "$OUT/xcode.log" 2>&1
code=$?
set -e
grep -E 'error:|warning: .*deprecated' "$OUT/xcode.log" | grep -v '^ld: warning' | head -n 40 || true
if [ "$code" != "0" ]; then
  echo "xcodebuild failed with exit code $code"
  tail -n 60 "$OUT/xcode.log"
  exit 1
fi

# CMake sets the products' directory to the project's; Xcode's DerivedData is the fallback.
APP="$(find "$EXPORT/proj" ~/Library/Developer/Xcode/DerivedData -type d -name '*.app' -path '*Release-iphoneos*' 2>/dev/null | head -n 1)"
if [ -z "$APP" ]; then
  echo "No .app built"
  exit 1
fi
echo "== Package $APP"
STAGE="$(mktemp -d)"
mkdir "$STAGE/Payload"
cp -R "$APP" "$STAGE/Payload/"
(cd "$STAGE" && zip -qry "$OUT/SpaceFlight.ipa" Payload)
rm -rf "$STAGE"

/usr/libexec/PlistBuddy -c 'Print :CFBundleIdentifier' -c 'Print :CFBundleDisplayName' -c 'Print :MinimumOSVersion' "$APP/Info.plist"
lipo -info "$APP/$(/usr/libexec/PlistBuddy -c 'Print :CFBundleExecutable' "$APP/Info.plist")"
du -sh "$APP" "$OUT/SpaceFlight.ipa"
